import os
from typing import Any, Dict, List, Optional

from openai import AzureOpenAI


def _normalize_messages(messages: Any) -> List[Dict[str, str]]:
    if messages is None:
        return [{"role": "user", "content": "Hello"}]
    if isinstance(messages, str):
        return [{"role": "user", "content": messages}]
    normalized: List[Dict[str, str]] = []
    for msg in messages:
        if isinstance(msg, dict) and "role" in msg and "content" in msg:
            normalized.append({"role": str(msg["role"]), "content": str(msg["content"])})
        elif isinstance(msg, (tuple, list)) and len(msg) >= 2:
            normalized.append({"role": str(msg[0]), "content": str(msg[1])})
        else:
            normalized.append({"role": "user", "content": str(msg)})
    return normalized


def _resolve_deployment_name(client: AzureOpenAI, model_or_deployment: str) -> str:
    try:
        deployments = client.models.list()
        for item in deployments:
            item_id = getattr(item, "id", None) or (item.get("id") if isinstance(item, dict) else None)
            if item_id == model_or_deployment:
                return model_or_deployment
    except Exception:
        pass
    return model_or_deployment


def invoke_managed_model(
    prompt_or_messages: Any,
    model_or_deployment: Optional[str] = None,
    temperature: float = 0.2,
    max_tokens: int = 512,
) -> str:
    endpoint = os.environ["AZURE_OPENAI_ENDPOINT"]
    api_key = os.environ["AZURE_OPENAI_API_KEY"]
    api_version = os.getenv("AZURE_OPENAI_API_VERSION", "2024-06-01")

    client = AzureOpenAI(
        api_key=api_key,
        azure_endpoint=endpoint,
        api_version=api_version,
    )

    deployment = model_or_deployment or os.getenv("AZURE_OPENAI_DEPLOYMENT", "gpt-4o-mini")
    deployment = _resolve_deployment_name(client, deployment)

    messages = _normalize_messages(prompt_or_messages)

    response = client.chat.completions.create(
        model=deployment,
        messages=messages,
        temperature=temperature,
        max_tokens=max_tokens,
    )

    choice = response.choices[0]
    content = getattr(choice.message, "content", None)
    if content is None:
        content = ""
    return content
